async function pageFunction({sendRequest}) {
 const index = await sendRequest({url:"https://de-linker.com/sitemaps.xml"});
 const rows=[{url:"https://de-linker.com/sitemaps.xml",status:index.statusCode,xml:index.body}];
 for (const m of index.body.matchAll(/<loc>([^<]+)<\/loc>/g)) {
  const url=m[1].replaceAll("&amp;","&");
  if (!url.startsWith("https://de-linker.com/") || !url.endsWith(".xml")) throw new Error("Unexpected sitemap URL");
  const r=await sendRequest({url}); rows.push({url,status:r.statusCode,xml:r.body});
 }
 return rows;
}
